The invariant is that `size_` stays between 0 and 17, and `head_` always identifies the next element to pop when the queue is nonempty. The live elements occupy `size_` consecutive positions starting at `head_`, wrapping modulo 17; the next push writes at `(head_ + size_) % 17`. A full queue rejects pushes without changing its state, and an empty queue returns no value on pop.

```cpp
#include <array>
#include <cstddef>
#include <iostream>
#include <optional>
#include <stdexcept>

class BoundedFIFO {
public:
    static constexpr std::size_t capacity = 17;

    bool push(int value) {
        if (size_ == capacity) {
            return false;
        }
        data_[(head_ + size_) % capacity] = value;
        ++size_;
        return true;
    }

    std::optional<int> pop() {
        if (size_ == 0) {
            return std::nullopt;
        }
        const int value = data_[head_];
        head_ = (head_ + 1) % capacity;
        --size_;
        return value;
    }

    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == capacity; }

private:
    std::array<int, capacity> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

void require(bool condition, const char* message) {
    if (!condition) {
        throw std::runtime_error(message);
    }
}

int main() {
    BoundedFIFO queue;

    require(!queue.pop().has_value(), "Empty pop failed");

    // Fill all 17 slots.
    for (int i = 0; i < 17; ++i) {
        require(queue.push(i), "Initial fill failed");
    }
    require(queue.full(), "Queue should be full");

    // Reject overflow without modifying the queue.
    require(!queue.push(999), "Overflow should be rejected");
    require(queue.size() == 17, "Overflow changed size");

    // Drain and verify FIFO order and unchanged contents.
    for (int i = 0; i < 17; ++i) {
        require(queue.pop() == std::optional<int>{i},
                "Initial drain order failed");
    }
    require(queue.empty(), "Queue should be empty");
    require(!queue.pop().has_value(), "Empty pop should fail");

    // Leave two live elements, then push across the array boundary.
    for (int i = 0; i < 12; ++i) {
        require(queue.push(i), "Wrap setup push failed");
    }
    for (int i = 0; i < 10; ++i) {
        require(queue.pop() == std::optional<int>{i},
                "Wrap setup pop failed");
    }
    // Writes use slots 12..16, then 0..4.
    for (int i = 12; i < 22; ++i) {
        require(queue.push(i), "Wrapped push failed");
    }
    require(queue.size() == 12, "Wrapped size failed");
    // Reads use slots 10..16, then 0..4.
    for (int i = 10; i < 22; ++i) {
        require(queue.pop() == std::optional<int>{i},
                "Wrapped FIFO order failed");
    }
    require(queue.empty(), "Final queue should be empty");
    require(!queue.pop().has_value(), "Final empty pop failed");

    std::cout << "All FIFO tests passed\n";
}
```

Compile and run with `g++ -std=c++17 -Wall -Wextra -pedantic fifo.cpp -o fifo && ./fifo`. This implementation stores integers, performs push and pop in constant time, and assumes single-threaded use or external synchronization.
